/* The crypto imports seen from a WebAssembly app: the hand-encoded modules of wasm_crypto_fixtures.h (generated by
 * tests/unit/tools/gen_wasm_crypto_fixtures.py) run as processes. Checks: a digest and an AEAD tag come out right through
 * the imports; the handles of an app that exits without finishing them are freed by the sweep; the keystore import
 * needs the crypto.keys permission. */
#include <string.h>

#include "nema/nema.h"
#include "pal/papp.h"
#include "test.h"
#include "wasm_crypto_fixtures.h"

static int host_with(const uint8_t *mod, size_t n, uint32_t perms) {
    uint8_t *img = nema_alloc(NEMA_MEM_ANY, nema_self()->owner, n);
    if (!img) return 125;
    memcpy(img, mod, n);
    pal_papp_t app;
    memset(&app, 0, sizeof(app));
    strcpy(app.id, "test");
    app.api = 1;
    app.mem_kb = 64;
    app.stack_kb = 16;
    app.perms = perms;
    app.payload = img;
    app.payload_len = n;
    return pal_wasm_run(&app, img, 0, NULL);
}

static int app_hash_abc(int argc, char **argv) { (void)argc, (void)argv; return host_with(WASM_HASH_ABC, sizeof(WASM_HASH_ABC), 0); }
static int app_hash_leak(int argc, char **argv) { (void)argc, (void)argv; return host_with(WASM_HASH_LEAK, sizeof(WASM_HASH_LEAK), 0); }
static int app_aead_rfc(int argc, char **argv) { (void)argc, (void)argv; return host_with(WASM_AEAD_RFC8439, sizeof(WASM_AEAD_RFC8439), 0); }
static int app_keys_denied(int argc, char **argv) { (void)argc, (void)argv; return host_with(WASM_KEY_LIST, sizeof(WASM_KEY_LIST), 0); }
static int app_keys_granted(int argc, char **argv) {
    (void)argc, (void)argv;
    return host_with(WASM_KEY_LIST, sizeof(WASM_KEY_LIST), PAL_PERM_CRYPTO_KEYS);
}

static const nema_app_t APPS[] = {
    {"wasm-hash-abc", "SHA-256 of abc through the hash imports", app_hash_abc, 0, 0},
    {"wasm-hash-leak", "three hash handles, never finished", app_hash_leak, 0, 0},
    {"wasm-aead-rfc", "ChaCha20-Poly1305 seal of RFC 8439 2.8.2", app_aead_rfc, 0, 0},
    {"wasm-key-list-denied", "key_list without crypto.keys", app_keys_denied, 0, 0},
    {"wasm-key-list-granted", "key_list with crypto.keys", app_keys_granted, 0, 0},
};

static size_t proc_bytes(void) {
    size_t total = 0;
    for (int i = 0; i < NEMA_PROC_MAX; i++) {
        nema_owner_stat_t s;
        if (!nema_mem_owner_stat((nema_owner_t)(NEMA_OWNER_PROC_BASE + i), &s)) continue;
        total += s.used[NEMA_MEM_INTERNAL] + s.used[NEMA_MEM_DMA] + s.used[NEMA_MEM_EXTERNAL] + s.stack;
    }
    return total;
}

/* proc_bytes() once it has come back to want, or after a second: a process's stack is released when its task ends, a moment
 * after nema_proc_wait has returned the exit code, so a slow machine still sees it right after the wait. */
static size_t settled_bytes(size_t want) {
    size_t b = proc_bytes();
    for (int i = 0; i < 100 && b != want; i++) {
        nema_port_sleep_ms(10);
        b = proc_bytes();
    }
    return b;
}

static nema_owner_t owner_of(nema_pid_t pid) {
    nema_proc_t *p = nema_proc_get(pid);
    return p ? p->owner : NEMA_OWNER_KERNEL;
}

TEST(sha256_of_abc_through_the_imports) {
    nema_spawn_t sp = {.name = "wasm-hash-abc"};
    nema_pid_t pid;
    CHECK(nema_proc_spawn(&sp, &pid) == NEMA_OK);
    int code = -1;
    CHECK(nema_proc_wait(pid, &code, 3000) == NEMA_OK);
    CHECK_EQ(code, 0xba); /* first byte of SHA-256("abc") */
}

TEST(aead_tag_through_the_imports) {
    nema_spawn_t sp = {.name = "wasm-aead-rfc"};
    nema_pid_t pid;
    CHECK(nema_proc_spawn(&sp, &pid) == NEMA_OK);
    int code = -1;
    CHECK(nema_proc_wait(pid, &code, 3000) == NEMA_OK);
    CHECK_EQ(code, 0x1a); /* first byte of the RFC 8439 tag 1ae10b59... */
}

TEST(the_sweep_frees_the_crypto_tables_of_an_app_that_exits_early) {
    size_t base = settled_bytes(0); /* the processes of the test before have let go of their stacks */
    nema_spawn_t sp = {.name = "wasm-hash-leak"};
    nema_pid_t pid;
    CHECK(nema_proc_spawn(&sp, &pid) == NEMA_OK);
    nema_owner_t o = owner_of(pid);
    int code = -1;
    CHECK(nema_proc_wait(pid, &code, 3000) == NEMA_OK);
    CHECK_EQ(code, 0);
    nema_owner_stat_t s;
    CHECK(nema_mem_owner_stat(o, &s));
    CHECK(s.peak >= 4096u); /* the table (8 digests, 8 ciphers, 8 keys) was charged to the process */
    CHECK_EQ(settled_bytes(base), base);
}

TEST(key_list_is_refused_without_the_crypto_keys_permission) {
    nema_spawn_t sp = {.name = "wasm-key-list-denied"};
    nema_pid_t pid;
    CHECK(nema_proc_spawn(&sp, &pid) == NEMA_OK);
    int code = -1;
    CHECK(nema_proc_wait(pid, &code, 3000) == NEMA_OK);
    CHECK_EQ(code, NEMA_ERR_PERM); /* the app's exit status is the call's result */
}

TEST(key_list_runs_with_the_crypto_keys_permission) {
    nema_spawn_t sp = {.name = "wasm-key-list-granted"};
    nema_pid_t pid;
    CHECK(nema_proc_spawn(&sp, &pid) == NEMA_OK);
    int code = -1;
    CHECK(nema_proc_wait(pid, &code, 3000) == NEMA_OK);
    CHECK_EQ(code, 0); /* no keystore on this host mount: an empty list */
}

int main(void) {
    nema_config_t cfg = {.console_log = false};
    nema_init(&cfg);
    for (size_t i = 0; i < NEMA_ARRAY_SIZE(APPS); i++) nema_app_register(&APPS[i]);
    RUN(sha256_of_abc_through_the_imports);
    RUN(aead_tag_through_the_imports);
    RUN(the_sweep_frees_the_crypto_tables_of_an_app_that_exits_early);
    RUN(key_list_is_refused_without_the_crypto_keys_permission);
    RUN(key_list_runs_with_the_crypto_keys_permission);
    return TEST_DONE();
}
